// Generator for RANDOMISED VALID INPUTS: well-formed bencode documents.
// Emits one bash-quoted argv line per document, using ANSI-C ($'...') quoting
// so control characters never put a literal newline into the case file.

const seed = Number(process.argv[2] ?? 1);
const count = Number(process.argv[3] ?? 300);

// deterministic PRNG (mulberry32) so runs are reproducible
let state = seed >>> 0;
function rnd() {
  state = (state + 0x6d2b79f5) >>> 0;
  let t = state;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
const ri = (n) => Math.floor(rnd() * n);
const pick = (a) => a[ri(a.length)];

// ---------------------------------------------------------------- payloads
// ASCII 1..127 only (str.encode('ascii')); NUL cannot travel through argv.
const PUNCT = "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~";
const LETTERS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
const DIGITS = '0123456789';
const CTRL = '\x01\x02\x03\x07\x08\x09\x0a\x0b\x0c\x0d\x1b\x1f\x7f';
const BENCODE_SIGILS = 'ilde:'; // structural chars inside payloads are fun

function randChar() {
  const r = rnd();
  if (r < 0.34) return pick(LETTERS);
  if (r < 0.46) return pick(DIGITS);
  if (r < 0.72) return pick(PUNCT); // heavy on punctuation + quotes + backslash
  if (r < 0.86) return pick(CTRL);
  if (r < 0.94) return pick(BENCODE_SIGILS);
  return String.fromCharCode(1 + ri(127)); // anything printable-or-not in ASCII
}

function randBytesPayload() {
  const r = rnd();
  let len;
  if (r < 0.08) len = 0;
  else if (r < 0.30) len = 1;
  else if (r < 0.75) len = 2 + ri(10);
  else if (r < 0.95) len = 12 + ri(30);
  else len = 60 + ri(140);
  let s = '';
  for (let i = 0; i < len; i += 1) s += randChar();
  return s;
}

// bencoded byte string with a CORRECT length prefix
function encByteString() {
  const p = randBytesPayload();
  return { text: `${p.length}:${p}`, kind: 'bytes' };
}

function encInt() {
  const r = rnd();
  let digits;
  if (r < 0.30) digits = String(ri(100));
  else if (r < 0.50) digits = String(ri(1000000));
  else if (r < 0.62) digits = '0';
  else if (r < 0.76) {
    // leading zeros (bencoder accepts them: i042e -> 42)
    digits = '0'.repeat(1 + ri(4)) + String(ri(1000));
  } else if (r < 0.90) {
    // very large magnitudes -> arbitrary precision
    let d = String(1 + ri(9));
    const extra = 15 + ri(45);
    for (let i = 0; i < extra; i += 1) d += pick(DIGITS);
    digits = d;
  } else {
    digits = String(ri(2 ** 31));
  }
  const neg = rnd() < 0.35 ? '-' : '';
  return { text: `i${neg}${digits}e`, kind: 'int' };
}

// dict keys must be hashable (bytes or int) for the document to stay valid
function encHashableKey() {
  return rnd() < 0.78 ? encByteString() : encInt();
}

function encList(depth) {
  const n = ri(5);
  let body = '';
  for (let i = 0; i < n; i += 1) body += encValue(depth + 1).text;
  return { text: `l${body}e`, kind: 'list' };
}

function encDict(depth) {
  const n = ri(4);
  const keys = [];
  let body = '';
  for (let i = 0; i < n; i += 1) {
    // sometimes repeat an earlier key: dict(zip(...)) keeps first position,
    // last value wins
    let k;
    if (keys.length > 0 && rnd() < 0.22) k = pick(keys);
    else {
      k = encHashableKey().text;
      keys.push(k);
    }
    body += k + encValue(depth + 1).text;
  }
  return { text: `d${body}e`, kind: 'dict' };
}

function encValue(depth) {
  const r = rnd();
  if (depth >= 5 || r < 0.42) return rnd() < 0.62 ? encByteString() : encInt();
  if (r < 0.74) return encList(depth);
  return encDict(depth);
}

// --------------------------------------------------------------- quoting
// Always ANSI-C quote: escape backslash and single quote, hex-escape every
// byte outside printable ASCII. Exactly two hex digits so bash never merges
// an escape with a following literal hex character.
function shQuote(s) {
  let out = "$'";
  for (let i = 0; i < s.length; i += 1) {
    const c = s[i];
    const code = s.charCodeAt(i);
    if (code === 0) throw new Error('NUL cannot travel through argv');
    if (c === '\\') out += '\\\\';
    else if (c === "'") out += "\\'";
    else if (code < 0x20 || code >= 0x7f) out += `\\x${code.toString(16).padStart(2, '0')}`;
    else out += c;
  }
  return out + "'";
}

const lines = [];
for (let i = 0; i < count; i += 1) {
  const doc = encValue(0);
  lines.push(`--a ${shQuote(doc.text)}`);
}
process.stdout.write(lines.join('\n') + '\n');

